INSERT INTO users (clinic_id,full_name,email,password_hash,cpf,role) SELECT clinic_id,'Recepcionista QA Ficticia','recepcao.qa@example.com',password_hash,'00000000003','RECEPTIONIST' FROM users WHERE email='admin.demo@example.com';
INSERT INTO users (clinic_id,full_name,email,password_hash,clinical_password_hash,cpf,role) SELECT clinic_id,'Segundo Dentista QA Ficticio','dentista2.qa@example.com',password_hash,clinical_password_hash,'00000000004','DENTIST' FROM users WHERE email='dentista.demo@example.com';
INSERT INTO dentists(user_id,cro_number,cro_state) SELECT id,'DEMO-0002','SP' FROM users WHERE email='dentista2.qa@example.com';
INSERT INTO appointments(clinic_id,patient_id,dentist_id,scheduled_at,duration_minutes,status,notes) SELECT p.clinic_id,p.id,d.id,now()-interval '2 days',30,'SCHEDULED','QA navegacao: consulta passada para concluir' FROM patients p CROSS JOIN dentists d JOIN users u ON u.id=d.user_id WHERE p.medical_record_number='DEMO-001' AND u.email='dentista.demo@example.com';
INSERT INTO appointments(clinic_id,patient_id,dentist_id,scheduled_at,duration_minutes,status,notes) SELECT p.clinic_id,p.id,d.id,now()-interval '1 day',30,'CONFIRMED','QA navegacao: consulta passada para ausencia' FROM patients p CROSS JOIN dentists d JOIN users u ON u.id=d.user_id WHERE p.medical_record_number='DEMO-003' AND u.email='dentista.demo@example.com';
INSERT INTO appointments(clinic_id,patient_id,dentist_id,scheduled_at,duration_minutes,status,notes) SELECT p.clinic_id,p.id,d.id,'2031-02-10T13:00:00+00',30,'SCHEDULED','QA navegacao: consulta de outro dentista' FROM patients p CROSS JOIN dentists d JOIN users u ON u.id=d.user_id WHERE p.medical_record_number='DEMO-003' AND u.email='dentista2.qa@example.com';
